(* [comment removed for export] *)

Definition SHCOUNT_DTOR_STATE_STACK : Z := 48 + STATE_DTOR_STACK.

(* [comment removed for export] *)
Definition scs_X (stb implb : Z) (Fb : fbv) : list (Z * Z) := (stb, stb + 312) :: sd_X implb Fb.

Section W.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

  Definition shcount_dtor_state_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (stb implb lo B : Z) (S : statev) (I : implv) (errv : word) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (s' : PState) (pf p : bptr),
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp)
      /\ rw_cells rsegs m' (errno_addr tp) [C4 errv] /\ hs_rauxv_ok H m' B
      /\ In (p, stb, SZ_SPCI_STATE) LB
      /\ (st_fb S <> FB_empty -> In (pf, fb_begin (st_fb S), fb_cap (st_fb S)) LB)
      /\ hs_RHEAP H s' (hs_lb_remove H p (sd_LB H (st_fb S) pf LB)) m'
      /\ ImplBlock (hs_lb_remove H p (sd_LB H (st_fb S) pf LB)) m' implb (impl_weak I 1)
      /\ XStatics m'
      /\ xpres LB (bv_unsigned sp) (scs_X stb implb (st_fb S)) m m'.

  Definition shcount_dtor_state_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (PC stb ioc implb lo B : Z) (S : statev) (ds : list byte) (I : implv) (errv : word),
      a0 = Z_to_bv 64 PC ->
      (* [comment removed for export] *)
      ro_cells rsegs m PC [C8 (wz stb)] -> (PC + 8 <= lo \/ bv_unsigned sp <= PC) ->
      (* [comment removed for export] *)
      StateBlock LB m stb ioc implb S ds -> st_hdr S = mkSPC VP_SPCI_STATE 1 1 1 ->
      (* [comment removed for export] *)
      ImplBlock LB m implb I -> spc_weak (im_hdr I) = 2 ->
      (stb + SZ_SPCI_STATE <= implb \/ implb + SZ_SPCI_IMPL <= stb) ->
      (0 < im_vcap I -> stb + SZ_SPCI_STATE <= im_vb I \/ im_vb I + 8 * im_vcap I <= stb) ->
      (0 < im_vcap I -> im_vb I + 8 * im_vcap I <= implb \/ implb + SZ_SPCI_IMPL <= im_vb I) ->
      (st_fb S <> FB_empty -> fb_off (st_fb S) stb SZ_SPCI_STATE /\ fb_off (st_fb S) implb SZ_SPCI_IMPL
                              /\ (0 < im_vcap I -> fb_off (st_fb S) (im_vb I) (8 * im_vcap I))) ->
      XStatics m ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B ->
      stk rsegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - SHCOUNT_DTOR_STATE_STACK ->
      rw_cells rsegs m (errno_addr tp) [C4 errv] -> mem_inv rsegs m -> tp = Z_to_bv 64 RATP ->
      bv_unsigned ra mod 2 = 0 ->
      hs_SR H (shcount_dtor_state_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB stb implb lo B S I errv m mo)
        (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (Z_to_bv 64 P_SHCOUNT_DTOR) fc None m (seg_rom rsegs)) mo).
Scheme kc__4 := Elimination for Corelib.Init.Logic.or Sort Prop.
Scheme kc__5 := Elimination for LinuxProcessSemantics.LinuxProcessSem.Run.config Sort Prop.
Scheme kc__6 := Elimination for Corelib.Init.Specif.sumbool Sort Prop.

