  fun ms' => exists m',
    ms' = MS (mkR (Z_to_bv 64 P_BSD_RET1) (Z_to_bv 64 (bv_unsigned sp + -16)) gp tp t0 t1 t2 (Z_to_bv 64 bs) s1 (Z_to_bv 64 bs) a1 a2 a3 a4 a5 a6 a7
