(* [comment removed for export] *)
Definition bsd_seg2_post (sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (stb lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR (Z_to_bv 64 P_BSD_RET2) sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (stb + 32)) a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_STATE_REMOVE) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp).

Lemma bsd_seg2 : forall (rax : word) sp gp tp t0 t1 t2 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (bs stb lo : Z),
  ro_cells rsegs m bs [C8 (wz (stb + 32))] -> bv_unsigned sp + 16 <= bs -> 0 < stb -> stb + 312 <= hceil ->
  stk rsegs m lo (bv_unsigned sp) -> lo + 16 <= bv_unsigned sp -> hceil <= lo ->
  mem_inv rsegs m ->
  evt rsegs (bsd_seg2_post sp gp tp (Z_to_bv 64 bs) s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc stb lo m)
    (MS (mkR rax sp gp tp t0 t1 t2 (Z_to_bv 64 bs) s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_BSD_RET1) fc None m (seg_rom rsegs)).
