Definition STREAM_DTOR_STACK : Z := 16 + SHCOUNT_DTOR_STATE_STACK.

(* [comment removed for export] *)
Definition bsd_X (bs stb implb vb vcap : Z) (Fb : fbv) : list (Z * Z) :=
  (bs + 16, bs + 32) :: (stb, stb + 312) :: (implb, implb + 96) :: (vb, vb + 8 * vcap)
  :: (if fb_begin Fb =? 0 then [] else [(fb_begin Fb, fb_end Fb)]).

Section W2.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

  Definition stream_dtor_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (bs stb implb vb i vcap lo B : Z) (S : statev) (errv : word) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (s' : PState) (pf p : bptr),
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp)
      /\ rw_cells rsegs m' (errno_addr tp) [C4 errv] /\ hs_rauxv_ok H m' B
      /\ In (p, stb, SZ_SPCI_STATE) LB
      /\ (st_fb S <> FB_empty -> In (pf, fb_begin (st_fb S), fb_cap (st_fb S)) LB)
      /\ hs_RHEAP H s' (hs_lb_remove H p (sd_LB H (st_fb S) pf LB)) m'
      /\ rw_cells rsegs m' bs (BasicStreamCells stb)
      /\ ImplBlock (hs_lb_remove H p (sd_LB H (st_fb S) pf LB)) m' implb (mkIMPL (mkSPC VP_SPCI_IMPL 1 1 i) 0 vb [] vcap)
      /\ XStatics m'
      /\ xpres LB (bv_unsigned sp) (bsd_X bs stb implb vb vcap (st_fb S)) m m'.

  Definition stream_dtor_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (bs stb ioc implb vb i vcap lo B : Z) (S : statev) (ds : list byte) (errv : word),
      a0 = Z_to_bv 64 bs ->
      (* [comment removed for export] *)
      rw_cells rsegs m bs (BasicStreamCells stb) -> bv_unsigned sp <= bs -> bs + SZ_BS <= B -> bs mod 8 = 0 ->
      (* [comment removed for export] *)
      StateBlock LB m stb ioc implb S ds -> st_hdr S = mkSPC VP_SPCI_STATE 1 1 1 -> st_lk S = 0 ->
      (* [comment removed for export] *)
      ImplBlock LB m implb (mkIMPL (mkSPC VP_SPCI_IMPL 1 2 i) 0 vb [stb + 32] vcap) ->
      (stb + SZ_SPCI_STATE <= implb \/ implb + SZ_SPCI_IMPL <= stb) ->
      (stb + SZ_SPCI_STATE <= vb \/ vb + 8 * vcap <= stb) ->
      (vb + 8 * vcap <= implb \/ implb + SZ_SPCI_IMPL <= vb) ->
      (st_fb S <> FB_empty -> fb_off (st_fb S) stb SZ_SPCI_STATE /\ fb_off (st_fb S) implb SZ_SPCI_IMPL /\ fb_off (st_fb S) vb (8 * vcap)) ->
      XStatics m ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B -> B < 2^64 ->
      stk rsegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - STREAM_DTOR_STACK ->
      rw_cells rsegs m (errno_addr tp) [C4 errv] -> mem_inv rsegs m -> tp = Z_to_bv 64 RATP ->
      bv_unsigned sp mod 16 = 0 -> bv_unsigned ra mod 2 = 0 ->
      hs_SR H (stream_dtor_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB bs stb implb vb i vcap lo B S errv m mo)
        (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (Z_to_bv 64 P_STREAM_DTOR) fc None m (seg_rom rsegs)) mo).
Scheme kc__7 := Elimination for Corelib.Init.Logic.False Sort Prop.

